"use client";

import * as React from "react";
import { Menubar as MenubarPrimitive } from "@base-ui/react/menubar";
import { Menu as MenuPrimitive } from "@base-ui/react/menu";
import { Icon } from "@iconify/react";

import { cn } from "@/lib/utils";
import { focusRing, menuItemBase, popoverSurface, popupMotion } from "./_shared";

// Base UI accepts a state function for className; these wrappers merge it with
// cn(), so they take a plain string.
type WithClassName<P> = Omit<P, "className"> & { className?: string };

type PositionerProps = Pick<MenuPrimitive.Positioner.Props, "align" | "alignOffset" | "side" | "sideOffset">;

/** The menu panel: the white floating panel, at least 12rem wide, padded 0.25rem. */
const menuPanel = cn(popoverSurface, popupMotion, "min-w-48 max-h-(--available-height) overflow-y-auto p-1");

/** One menu in the bar: its trigger and its panel. */
const MenubarMenu = MenuPrimitive.Root;

/** Groups related rows and gives a label something to name. */
const MenubarGroup = MenuPrimitive.Group;

/** Moves a menu panel to the end of the document body. */
const MenubarPortal = MenuPrimitive.Portal;

/** Wraps a nested menu: its sub-trigger and its sub-content. */
const MenubarSub = MenuPrimitive.SubmenuRoot;

/** Holds a set of radio rows where only one can be chosen. */
const MenubarRadioGroup = MenuPrimitive.RadioGroup;

/** Margin menubar: a row of menu names on a white toolbar strip with a hairline ring. */
const Menubar = React.forwardRef<HTMLDivElement, WithClassName<MenubarPrimitive.Props>>(
  ({ className, ...props }, ref) => (
    <MenubarPrimitive
      ref={ref}
      data-slot="menubar"
      className={cn("inline-flex h-8 items-center gap-0.5 rounded-lg bg-card p-0.5 shadow-sm", className)}
      {...props}
    />
  ),
);
Menubar.displayName = "Menubar";

/** A menu name in the bar: muted text that turns field grey while its menu is open. */
const MenubarTrigger = React.forwardRef<HTMLButtonElement, WithClassName<MenuPrimitive.Trigger.Props>>(
  ({ className, ...props }, ref) => (
    <MenuPrimitive.Trigger
      ref={ref}
      data-slot="menubar-trigger"
      className={cn(
        "inline-flex h-7 cursor-default select-none items-center rounded-md px-2.5 text-sm text-muted-foreground",
        "transition-colors duration-fast ease-(--ease-out) hover:bg-accent hover:text-foreground",
        focusRing,
        "data-[popup-open]:bg-(--field) data-[popup-open]:text-foreground",
        "data-[disabled]:pointer-events-none data-[disabled]:opacity-50",
        className,
      )}
      {...props}
    />
  ),
);
MenubarTrigger.displayName = "MenubarTrigger";

/** Margin menubar panel: the white floating panel, dropping from the start edge of its trigger. */
const MenubarContent = React.forwardRef<
  HTMLDivElement,
  WithClassName<MenuPrimitive.Popup.Props> & PositionerProps
>(({ className, align = "start", alignOffset = -2, side, sideOffset = 6, ...props }, ref) => (
  <MenuPrimitive.Portal>
    <MenuPrimitive.Positioner
      className="isolate z-50 outline-none"
      align={align}
      alignOffset={alignOffset}
      side={side}
      sideOffset={sideOffset}
    >
      <MenuPrimitive.Popup ref={ref} data-slot="menubar-content" className={cn(menuPanel, className)} {...props} />
    </MenuPrimitive.Positioner>
  </MenuPrimitive.Portal>
));
MenubarContent.displayName = "MenubarContent";

/** A nested menu panel that opens beside its row, level with the row's top. */
const MenubarSubContent = React.forwardRef<
  HTMLDivElement,
  WithClassName<MenuPrimitive.Popup.Props> & PositionerProps
>(({ className, align = "start", alignOffset = -4, side = "right", sideOffset = 4, ...props }, ref) => (
  <MenuPrimitive.Portal>
    <MenuPrimitive.Positioner
      className="isolate z-50 outline-none"
      align={align}
      alignOffset={alignOffset}
      side={side}
      sideOffset={sideOffset}
    >
      <MenuPrimitive.Popup
        ref={ref}
        data-slot="menubar-sub-content"
        className={cn(menuPanel, className)}
        {...props}
      />
    </MenuPrimitive.Positioner>
  </MenuPrimitive.Portal>
));
MenubarSubContent.displayName = "MenubarSubContent";

/** A row that opens a nested menu, with a caret at the end. */
const MenubarSubTrigger = React.forwardRef<
  HTMLElement,
  WithClassName<MenuPrimitive.SubmenuTrigger.Props> & { inset?: boolean }
>(({ className, inset, children, ...props }, ref) => (
  <MenuPrimitive.SubmenuTrigger
    ref={ref}
    data-slot="menubar-sub-trigger"
    className={cn(
      menuItemBase,
      "data-[popup-open]:bg-(--field) data-[popup-open]:text-accent-foreground",
      inset && "ps-8",
      className,
    )}
    {...props}
  >
    {children}
    <Icon icon="solar:alt-arrow-right-linear" className="ms-auto rtl:rotate-180" aria-hidden="true" />
  </MenuPrimitive.SubmenuTrigger>
));
MenubarSubTrigger.displayName = "MenubarSubTrigger";

/** A menu row, 2rem tall, that turns field grey under the pointer; destructive turns it red. */
const MenubarItem = React.forwardRef<
  HTMLElement,
  WithClassName<MenuPrimitive.Item.Props> & {
    inset?: boolean;
    variant?: "default" | "destructive";
  }
>(({ className, inset, variant = "default", ...props }, ref) => (
  <MenuPrimitive.Item
    ref={ref}
    data-slot="menubar-item"
    data-variant={variant}
    className={cn(
      menuItemBase,
      variant === "destructive" &&
        "text-destructive-text data-[highlighted]:bg-destructive/10 data-[highlighted]:text-destructive-text [&_svg]:text-current",
      inset && "ps-8",
      className,
    )}
    {...props}
  />
));
MenubarItem.displayName = "MenubarItem";

/** A row that toggles on and off, with an oxblood tick at the start when on. */
const MenubarCheckboxItem = React.forwardRef<HTMLElement, WithClassName<MenuPrimitive.CheckboxItem.Props>>(
  ({ className, children, ...props }, ref) => (
    <MenuPrimitive.CheckboxItem
      ref={ref}
      data-slot="menubar-checkbox-item"
      className={cn(menuItemBase, "ps-8", className)}
      {...props}
    >
      <span className="pointer-events-none absolute start-2 flex size-4 items-center justify-center">
        <MenuPrimitive.CheckboxItemIndicator>
          <Icon icon="solar:unread-linear" className="text-(--primary-text)!" aria-hidden="true" />
        </MenuPrimitive.CheckboxItemIndicator>
      </span>
      {children}
    </MenuPrimitive.CheckboxItem>
  ),
);
MenubarCheckboxItem.displayName = "MenubarCheckboxItem";

/** One choice in a radio group, with a small oxblood dot at the start when chosen. */
const MenubarRadioItem = React.forwardRef<HTMLElement, WithClassName<MenuPrimitive.RadioItem.Props>>(
  ({ className, children, ...props }, ref) => (
    <MenuPrimitive.RadioItem
      ref={ref}
      data-slot="menubar-radio-item"
      className={cn(menuItemBase, "ps-8", className)}
      {...props}
    >
      <span className="pointer-events-none absolute start-2 flex size-4 items-center justify-center">
        <MenuPrimitive.RadioItemIndicator>
          <span className="block size-1.5 rounded-full bg-primary" />
        </MenuPrimitive.RadioItemIndicator>
      </span>
      {children}
    </MenuPrimitive.RadioItem>
  ),
);
MenubarRadioItem.displayName = "MenubarRadioItem";

/** A small muted heading over a group of rows, used inside a group. */
const MenubarLabel = React.forwardRef<
  HTMLDivElement,
  WithClassName<MenuPrimitive.GroupLabel.Props> & { inset?: boolean }
>(({ className, inset, ...props }, ref) => (
  <MenuPrimitive.GroupLabel
    ref={ref}
    data-slot="menubar-label"
    className={cn("px-2.5 py-1.5 text-xs font-medium text-muted-foreground", inset && "ps-8", className)}
    {...props}
  />
));
MenubarLabel.displayName = "MenubarLabel";

/** A hairline between groups that runs to the panel's edges. */
const MenubarSeparator = React.forwardRef<HTMLDivElement, WithClassName<MenuPrimitive.Separator.Props>>(
  ({ className, ...props }, ref) => (
    <MenuPrimitive.Separator
      ref={ref}
      data-slot="menubar-separator"
      className={cn("-mx-1 my-1 h-px bg-border", className)}
      {...props}
    />
  ),
);
MenubarSeparator.displayName = "MenubarSeparator";

/** The keyboard shortcut at the end of a row, in small muted type. */
const MenubarShortcut = ({ className, ...props }: React.HTMLAttributes<HTMLSpanElement>) => (
  <span
    data-slot="menubar-shortcut"
    className={cn("ms-auto ps-4 text-xs text-muted-foreground", className)}
    {...props}
  />
);
MenubarShortcut.displayName = "MenubarShortcut";

export {
  Menubar,
  MenubarMenu,
  MenubarTrigger,
  MenubarContent,
  MenubarItem,
  MenubarSeparator,
  MenubarLabel,
  MenubarCheckboxItem,
  MenubarRadioGroup,
  MenubarRadioItem,
  MenubarPortal,
  MenubarSubContent,
  MenubarSubTrigger,
  MenubarGroup,
  MenubarSub,
  MenubarShortcut,
};
